ml" class=""><!--[-->Schedule Stop Pairs<!--]--></a>. All options below can be combined.<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/schedule_stop_pairs?origin_onestop_id=s-9q8yyugptw-sanfranciscocaltrainstation<!--]--></code><!--]--></td><td><!--[-->Find all Schedule Stop Pairs from origin. Accepts multiple Onestop IDs, separated by commas.<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/schedule_stop_pairs?destination_onestop_id=s-9q8yyugptw-sanfranciscocaltrainstation<!--]--></code><!--]--></td><td><!--[-->Find all Schedule Stop Pairs to a destination. Accepts multiple Onestop IDs, separated by commas.<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/schedule_stop_pairs?date=2015-08-05<!--]--></code><!--]--></td><td><!--[-->Find all Schedule Stop Pairs from origin on date<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/schedule_stop_pairs?service_from_date=2015-08-05<!--]--></code><!--]--></td><td><!--[-->Find all Schedule Stop Pairs in effect from a date<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/schedule_stop_pairs?service_before_date=2015-10-20<!--]--></code><!--]--></td><td><!--[-->Find all Schedule Stop Pairs in effect before a date<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/schedule_stop_pairs?origin_departure_between=09:00:00,09:10:00<!--]--></code><!--]--></td><td><!--[-->Find all Schedule Stop Pairs with origin_departure_time in a range<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/schedule_stop_pairs?trip=6507768-CT-14OCT-Combo-Weekday-01<!--]--></code><!--]--></td><td><!--[-->Find all Schedule Stop Pairs by trip identifier<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/schedule_stop_pairs?route_onestop_id=r-9q8y-richmond~dalycity~millbrae<!--]--></code><!--]--></td><td><!--[-->Find all Schedule Stop Pairs by route. Accepts multiple Onestop IDs, separated by commas.<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/schedule_stop_pairs?operator_onestop_id=o-9q9-caltrain<!--]--></code><!--]--></td><td><!--[-->Find all Schedule Stop Pairs by operator. Accepts multiple Onestop IDs, separated by commas.<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/schedule_stop_pairs?bbox=-121.0,35.0,-124.0,37.0<!--]--></code><!--]--></td><td><!--[-->Find all Schedule Stop Pairs originating within a bounding box<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/schedule_stop_pairs?active=true<!--]--></code><!--]--></td><td><!--[-->Schedule Stop Pairs from active FeedVersions<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/schedule_stop_pairs?import_level=2<!--]--></code><!--]--></td><td><!--[-->Schedule Stop Pairs from FeedVersion with a given import_level<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/feed_version_infos?feed_version_sha1=700753c9707f4fb203776d13fcb1e372d7b068fa<!--]--></code><!--]--></td><td><!--[-->FeedVersionInfo records for a given Feed Version<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/feed_version_infos?feed_onestop_id=f-9q9-caltrain<!--]--></code><!--]--></td><td><!--[-->FeedVersionInfo records for a given Feed<!--]--></td><!--]--></tr><tr><!--[--><td><!--[--><code><!--[-->GET<!--]--></code><!--]--></td><td><!--[--><code><!--[-->/api/v1/feed_version_infos?type=FeedVersionInfoStatistics<!--]--></code><!--]--></td><td><!--[-->FeedVersionInfo by info type<!--]--></td><!--]--></tr><!--]--></tbody><!--]--></table><h3 id="pagination-for-json-endpoints"><a href="#pagination-for-json-endpoints"><!--[-->Pagination for JSON endpoints<!--]--></a></h3><ul><!--[--><li><!--[--><code><!--[-->?offset=50<!--]--></code> is the index of the first entity to be displayed (starts with 0)<!--]--></li><li><!--[-->By default, 50 entities are displayed per page. To change the number, specify <code><!--[-->?per_page=1000<!--]--></code>.<!--]--></li><li><!--[-->To show the total number of results, use <code><!--[-->?total=true<!--]--></code><!--]--></li><!--]--></ul><h3 id="max-request-size"><a href="#max-request-size"><!--[-->Max Request Size<!--]--></a></h3><p><!--[-->If queries have not completed after two minutes, they will be killed and you will receive a timeout response from the Datastore. If your query times out, try reducing the <code><!--[-->per_page<!--]--></code> count, the bounding box size, etc. If your query seems as small as is possible, <a href="mailto:hello@transit.land" rel="noopener noreferrer"><!--[-->let us know<!--]--></a>.<!--]--></p><h3 id="format"><a href="#format"><!--[-->Format<!--]--></a></h3><ul><!--[--><li><!--[-->By default, responses are paginated JSON<!--]--></li><li><!--[-->Specify <code><!--[-->.geojson<!--]--></code> instead for GeoJSON on some endpoints. For example: <code><!--[-->/api/v1/stops.geojson?bbox=-122.4183,37.7758,-122.4120,37.7858<!--]--></code> and <code><!--[-->/api/v1/routes.geojson?operated_by=o-9q9-bayarearapidtransit<!--]--></code><!--]--></li><!--]--></ul><h2 id="api-authentication"><a href="#api-authentication"><!--[-->API authentication<!--]--></a></h2><p><!--[-->Any API calls that involve writing to the database (creating/editing/applying <a href="/documentation/datastore/changesets.html" class=""><!--[-->changesets<!--]--></a> or running the Feed Eater data ingestion pipeline) require authentication. Currently authentication is limited to Mapzen staff, although we&#39;re preparing to share editing and moderation authorization with outsider collaborators in the future.<!--]--></p></div></div></div></div></div><!--]--></div></div><footer class="footer" data-v-3ebf9d54 data-v-e5b13465><div class="columns" data-v-e5b13465><div class="column is-one-fifth" data-v-e5b13465><p class="content" data-v-e5b13465><a href="/" data-v-e5b13465>Transitland</a> is operated by <a href="https://www.interline.io" data-v-e5b13465>Interline</a>. </p><p class="content is-small" data-v-e5b13465> Transitland is a registered trademark of Interline Technologies LLC. </p></div><div class="column is-offset-one-fifth is-one-fifth has-text-left" data-v-e5b13465><h6 class="title is-6 mb-2" data-v-e5b13465> Browse </h6><ul data-v-e5b13465><li data-v-e5b13465><a href="/map/" data-v-e5b13465>Map</a></li><li data-v-e5b13465><a href="/places/" data-v-e5b13465>Places</a></li><li data-v-e5b13465><a href="/operators/" data-v-e5b13465>Operators</a></li><li data-v-e5b13465><a href="/feeds/" data-v-e5b13465>Source Feeds</a></li></ul></div><div class="column is-one-fifth has-text-left" data-v-e5b13465><h6 class="title is-6 mb-2" data-v-e5b13465> Use </h6><ul data-v-e5b13465><li data-v-e5b13465><a href="/plans-pricing/" data-v-e5b13465>Plans and Pricing</a></li><li data-v-e5b13465><a href="/datasets/" data-v-e5b13465>Datasets</a></li><li data-v-e5b13465><a href="https://status.interline.io" target="_blank" data-v-e5b13465>Status Dashboard <span class="icon is-small" data-v-e5b13465><i class="mdi mdi-open-in-new"></i></span></a></li><li data-v-e5b13465><a href="/terms" data-v-e5b13465>Terms of Service and Data Attributions</a></